-- V27: Add BlogPosts and BlogImages tables in accounts schema

CREATE TABLE IF NOT EXISTS accounts."BlogPosts" (
    "Id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Title" VARCHAR(255) NOT NULL,
    "Slug" VARCHAR(255) NOT NULL,
    "ContentMarkdown" TEXT NOT NULL,
    "Excerpt" TEXT NULL,
    "IsPublished" BOOLEAN NOT NULL DEFAULT FALSE,
    "PublishedAt" TIMESTAMP WITH TIME ZONE NULL,
    "CreatedAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "IsDeleted" BOOLEAN NOT NULL DEFAULT FALSE,
    "DeletedAt" TIMESTAMP WITH TIME ZONE NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS "IX_BlogPosts_Slug" ON accounts."BlogPosts" ("Slug");

CREATE TABLE IF NOT EXISTS accounts."BlogImages" (
    "Id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "FileName" VARCHAR(255) NOT NULL,
    "ContentType" VARCHAR(100) NOT NULL DEFAULT 'image/webp',
    "Data" BYTEA NOT NULL,
    "FileSize" BIGINT NOT NULL,
    "CreatedAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "IsDeleted" BOOLEAN NOT NULL DEFAULT FALSE,
    "DeletedAt" TIMESTAMP WITH TIME ZONE NULL
);

-- Ensure Admin role exists in AspNetRoles
INSERT INTO "AspNetRoles" ("Id", "Name", "NormalizedName")
VALUES (gen_random_uuid()::text, 'Admin', 'ADMIN')
ON CONFLICT ("NormalizedName") DO NOTHING;
